// there is one, otherwise whatever the current mode has to say.
func (m Model) renderInfoLine(width int) string {
	return m.footer.View(width, m.status())
}

// status is what the view derives on every frame. None of the five has a timer:
// a clone run outlives the three seconds a message gets, and the load, the
// selection, the missing session and the failed load last exactly as long as
// they last.
func (m Model) status() components.Status {
	switch {
	// Signed out and a failed load are states, not events: they are true for as
	// long as they are true, so they carry the error level and no timer (Rule
	// 128). A three-second message would leave an empty table explaining
	// nothing for the rest of the session.
	case !m.shared.IsAuthenticated:
		return components.Status{Text: notAuthenticatedLine(m.vocab()), Level: components.LevelError}
	case m.mode == ModeCloning && m.clone != nil:
		return components.Status{Text: m.cloneStatusLine()}
	case m.mode == ModeSelecting:
		return components.Status{Text: m.selectionStatusLine()}
	case m.error != "":
		return components.Status{Text: m.error, Level: components.LevelError}
	case m.loadingTree():
		return components.Status{Text: "Loading " + m.vocab().Name + " " + strings.ToLower(m.vocab().Namespaces) + "...", Spinner: true}
	// A level on screen from the index while the forge is asked again: the
	// rows are there, so this is the lowest-priority line, and it says what
	// is still coming rather than that anything is missing.
	case m.refreshing > 0:
		return components.Status{Text: "Updating from " + m.vocab().Name + "...", Spinner: true}
	}
	return components.Status{}
}

// selectionStatusLine states the selection in the only terms it can: the
// repository count is not known until discovery has run (decision 7), so what
// is shown is what was actually chosen.
func (m Model) selectionStatusLine() string {
	if m.selection.isEmpty() {
		return "Select groups and projects with space, then press enter"
	}
	roots, exclusions := m.selection.counts()
	line := plural(roots, "selection")
	if exclusions > 0 {
		line += " · " + plural(exclusions, "exclusion")
	}
		if nodeType == NodeTypeGroup {
			err = backend.DeleteNamespace(context.Background(), forge.Namespace{ID: id, Path: path}, permanentlyRemove)
		} else {
			err = backend.DeleteRepository(context.Background(), forge.Repository{ID: id, Path: path}, permanentlyRemove)
		}
		return DeleteCompleteMsg{Error: err, Target: path, DeletedNode: node}
	}
	// The row keeps its place and takes the spinner while the forge works — the
	// same treatment a create gets, and for the same reason: a delete is a
	// network call, and a row that vanished before the answer came would be
	// claiming something that has not happened yet.
	return m, jobs.Start(deleteRun(path, node.Name), work)
}

// removeNode drops node from level, by identity first and by ID as a fallback
// (a refresh may have replaced the pointer since the delete was asked).
func removeNode(level []*TreeNode, node *TreeNode) []*TreeNode {
	for i, n := range level {
		if n == node || (n.ID != "" && n.ID == node.ID) {
			return append(level[:i], level[i+1:]...)
		}
	}
	return level
}

// handleDeleteComplete handles DeleteCompleteMsg
func (m Model) handleDeleteComplete(msg DeleteCompleteMsg) (tea.Model, tea.Cmd) {
	if msg.Error != nil {
		log.Printf("ERROR [explorer] delete: %v", msg.Error)
		return m, m.footer.Error("Delete failed — check logs")
	}
	m.footer.Clear()

	if msg.DeletedNode == nil {
		m.updateTableRows()
		return m, nil
//
// No refresh: the forge has just told us what it made, so re-listing the whole
// tree to learn it would empty the table for the length of a second round trip.
// It is also what stops a create outliving a context switch from reloading the
// tree of the context it switched to.
//
// A failure goes to the footer rather than to m.error, which would replace the
// tree with an error screen — the one place the removed row cannot be seen.
func (m Model) handleGroupCreated(msg GroupCreatedMsg) (tea.Model, tea.Cmd) {
	if msg.Error != nil {
		log.Printf("ERROR [explorer] create namespace: %v", msg.Error)
		m.settleCreating(msg.Target, nil)
		return m, m.footer.Error("Failed to create " + msg.Target + " — check logs")
	}

	node := nodeFromNamespace(msg.Namespace, nil)
	m.settleCreating(msg.Target, node)
	m.levelChanged(node.Parent)
	m.selectRow(node.FullPath)
	return m, indexCreated(node)
}

// handleProjectCreated resolves the placeholder row in place. See
// handleGroupCreated for why there is no refresh.
func (m Model) handleProjectCreated(msg ProjectCreatedMsg) (tea.Model, tea.Cmd) {
	if msg.Error != nil {
		log.Printf("ERROR [explorer] create repository: %v", msg.Error)
		m.settleCreating(msg.Target, nil)
		if msg.TemplateUnavailable {
			return m, m.footer.Error("Could not fetch the template — " + msg.Target + " was not created. Check logs")
		}
		return m, m.footer.Error("Failed to create " + msg.Target + " — check logs")
	}

	// The project exists whatever the template did, so the row settles either
	// way; only the message differs.
		// glyph (D8); any other observed state shows it with the glyph.
		a.Detail = RowDetail{Lead: oneLine(q.ObservedText)}
		if f.state != indicator.Idle && a.Detail.Lead != "" {
			a.Detail.Glyph = glyph
		}
	}
	return a
}

// FailureEvent is the 3-second Error a view posts when an operation fails:
// "Failed to <kind> <target> — <cause>".
func FailureEvent(kind jobs.Kind, target, cause string) string {
	return "Failed to " + string(kind) + " " + targetDisplay(target) + causeSuffix(kind, cause)
}

// rowFacts is the single computation behind RowState and DescribeRow.
type rowFacts struct {
	state    indicator.State
	active   []jobs.Active  // running first, then queued
	failures []jobs.Failure // newest first; the winner when state is Failed
}

func resolveRow(q RowQuery) rowFacts {
	f := rowFacts{
		active:   jobs.ActiveOn(q.Runs, q.Context, q.Target, q.Kinds...),
		failures: jobs.FailuresOn(q.Failures, q.Context, q.Target, q.Kinds...),
	}
	slices.SortStableFunc(f.failures, func(a, b jobs.Failure) int { return b.At.Compare(a.At) })
	act := indicator.Activity{Failed: len(f.failures) > 0, Observed: q.Observed}
	for _, a := range f.active {
		act.Running = act.Running || a.Item.State == jobs.ItemRunning
		act.Queued = act.Queued || a.Item.State == jobs.ItemQueued
	}
	f.state = indicator.Resolve(act)
	return f
}
