package explorer

import (
	"github.com/anthnel/devdesk/internal/command"
	"github.com/anthnel/devdesk/internal/jobs"
)

// What this view knows about the work it has started is a snapshot the router
// hands it, and nothing else (D1).
//
// The clone was already registered; the create and the delete were not, and
// they are the two that talk to a forge over the network. Left outside, each
// would have needed its own flag, its own spinner chain and its own guard —
// which is the fourth bookkeeping the package doc of internal/jobs opens by
// describing, and the spinner chain is the half that fails silently: this
// view's own chain stops on `!m.loading` (handleSpinnerTick), so a frame
func TestAFrameMovesTheRowSpinner(t *testing.T) {
	m := loadedModel(t)
	m, _ = step(t, m, components.CreationFormSubmitMsg{FormType: components.FormTypeGroup, Name: "new"})
	m = feed(t, m, jobs.ChangedMsg{Runs: []jobs.Run{createRun("new", "new")}})

	for _, blink := range []bool{true, false} {
		m = feed(t, m, jobs.FrameMsg{Frame: "X", Blink: blink})
		row, ok := rowFor(m, "new")
		if !ok {
			t.Fatal("the placeholder row is gone")
		}
		if row.Activity != indicator.Running {
			t.Errorf("Activity = %v, want Running", row.Activity)
		}
		if line := treeLine(t, m, "new"); !strings.Contains(line, indicator.Glyph(indicator.Running, blink)) {
			t.Errorf("blink=%v: row lacks the dot:\n%s", blink, line)
		}
		if got := restIcon(row); got == "X" {
			t.Errorf("the spinner frame leaked into the resting icon: %q", got)
		}
	}
	if len(m.jobs) != 1 {
		t.Errorf("the held runs = %d after a frame, want the 1 from the snapshot", len(m.jobs))
	}

// A working row's dot comes from the broadcast: the registry snapshot says
// the row works, FrameMsg.Blink says which half of the blink it is in. Neither
// goes through this view's own chain, which stops when the tree settles.
func TestAWorkingRowTakesItsFrameFromTheBroadcast(t *testing.T) {
	m := loadedModel(t)
	m, _ = step(t, m, components.CreationFormSubmitMsg{FormType: components.FormTypeGroup, Name: "new"})

	m = feed(t, m, jobs.ChangedMsg{
		Runs: []jobs.Run{createRun("new", "new")},
	})
	m = feed(t, m, jobs.FrameMsg{Frame: "⣾", Blink: true})

	row, ok := rowFor(m, "new")
	if !ok {
		t.Fatal("the placeholder row is gone")
	}
	if row.Activity != indicator.Running {
		t.Errorf("row Activity = %v, want Running", row.Activity)
	}
	if got := restIcon(row); got == "⣾" {
		t.Errorf("rest icon = %q, the spinner frame must not reach the row", got)
	}
	if line := treeLine(t, m, "new"); !strings.Contains(line, indicator.Glyph(indicator.Running, true)) {
		t.Errorf("row lacks the dot:\n%s", line)
	}
